command:
if ([...game.combats].filter(combat => combat.isActive).length === 0)  {
    ChatMessage.create({
        speaker: {user: game.user.character},
        content: `<h3 style="color: #C0392B;">${game.i18n.format("FQCARDENGINE.WarningMsgSpellUseInCombat")}</h3>`
    });
} else if (game.user.character.system.fq.action.value !== game.user.character.system.fq.action.max) {
    ChatMessage.create({
        speaker: {user: game.user.character},
        content: `<h3 style="color: #C0392B;">${game.i18n.format("FQCARDENGINE.WarningMsgNotEnoughAction")}</h3>`
    });
} else {
    foundry.audio.AudioHelper.play({
        src: "modules/fq-card-engine/sounds/passive_spells/run.mp3",
        volume: 0.4,
        autoplay: true,
        loop: false
    }, true);
    ChatMessage.create({
        speaker: {user: game.user.character},
        content: `<h3 style="color: darkgreen;">${game.i18n.format("FQCARDENGINE.MacroMsgRun")}</h3>`
    });
    game.user.character.update({"system.fq.action.value": 0});
    game.user.character.createEmbeddedDocuments("ActiveEffect", [
            {
                label: "Pick 0",
                icon: "icons/sundries/gaming/rune-card.webp",
                origin: "FQ Effect",
                changes: [
                    {
                        key: "system.fq.cards.pick",
                        value: "0",
                        mode: 5
                    }
                ],
                duration: {
                    startTime: null,
                    rounds: 2,
                    turns: null
                },

                flags: {isFQEffects: true}
            }, {
                label: "Run",
                icon: "icons/skills/movement/feet-winged-boots-glowing-yellow.webp",
                origin: "FQ Effect",
                changes: [
                    {
                        key: "system.attributes.movement.walk",
                        value: "2",
                        mode: 1
                    },
                    {
                        key: "macro.tokenMagic",
                        value: "zoomblur",
                        mode: 0
                    }
                ],
                duration: {
                    startTime: null,
                    rounds: 1,
                    turns: null
                },
            }
        ]
    );
}
